def is_prime(n):
    if n < 2: return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0: return False
    return True

def get_nearest_prime(n):
    if is_prime(n): return n
    curr = n + 1
    while not is_prime(curr):
        curr += 1
    return curr

def unlock_door(input_list):
